package com.loanops.fincompass.matching;
import com.loanops.fincompass.simulation.*;import com.loanops.fincompass.twin.*;
import org.junit.jupiter.api.Test;import java.math.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import static com.loanops.fincompass.matching.MatchingModels.*;import static com.loanops.fincompass.simulation.SimulationModels.*;import static com.loanops.fincompass.twin.TwinModels.*;import static org.assertj.core.api.Assertions.*;
class MatchingEngineTest {
 private final MatchingEngine engine=new MatchingEngine();private final SimulationEngine simulation=new SimulationEngine();
 @Test void completeCandidatesAreSimulatedScoredAndRankedDeterministically(){var a=product(1,"4.0","4.5");var b=product(2,"4.5","5.5");var first=run(List.of(b,a));var second=run(List.of(a,b));assertThat(first).usingRecursiveComparison().ignoringCollectionOrder().isEqualTo(second);assertThat(first).allMatch(e->e.status()==Status.MATCHED_FOR_REVIEW&&e.score()!=null&&e.rank()!=null);assertThat(first.stream().filter(e->e.rank()==1).findFirst().orElseThrow().product().productTermId()).isEqualTo(1);assertThat(first).allSatisfy(e->assertThat(e.score().components().stream().map(ScoreComponent::weightedScore).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo(e.score().total()));}
 @Test void hardFiltersRunBeforeAnyScore(){var p=product(1,"4","5");p=copy(p,"FAILED",p.amountMin(),p.amountMax(),p.termMin(),p.termMax(),p.repaymentMethods(),p.eligibilityText());var e=run(List.of(p)).getFirst();assertThat(e.status()).isEqualTo(Status.FILTERED_OUT);assertThat(e.loanResult()).isNull();assertThat(e.score()).isNull();}
 @Test void explicitAmountTermAndRepaymentMismatchFilter(){var base=product(1,"4","5");for(var p:List.of(copy(base,"SERVING",d("600000000"),d("900000000"),1,50,List.of("AMORTIZING"),"known"),copy(base,"SERVING",d("1"),d("900000000"),31,40,List.of("AMORTIZING"),"known"),copy(base,"SERVING",d("1"),d("900000000"),1,50,List.of("BULLET"),"known")))assertThat(run(List.of(p)).getFirst().status()).isEqualTo(Status.FILTERED_OUT);}
 @Test void missingCriticalProductFieldsNeverReceiveScoreOrRank(){var p=product(1,"4","5");p=copy(p,"SERVING",null,null,null,null,null,null);var e=run(List.of(p)).getFirst();assertThat(e.status()).isEqualTo(Status.INSUFFICIENT_DATA);assertThat(e.score()).isNull();assertThat(e.rank()).isNull();assertThat(e.limitations()).contains("AMOUNT_RANGE_MISSING","TERM_RANGE_MISSING","EXACT_REPAYMENT_MAPPING_MISSING","ELIGIBILITY_MISSING");assertThat(e.loanResult()).isNotNull();}
 @Test void ratePolicyUsesAverageThenMaxThenMinWithoutBoundingAverage(){var p=product(1,"4","5");var avg=new ProductRecord(p.loanProductId(),p.productTermId(),p.termParentProductId(),p.productPublicationRunId(),p.termPublicationRunId(),p.productSourceRunId(),p.termSourceRunId(),p.productRawSnapshotId(),p.termRawSnapshotId(),p.productRawHash(),p.termRawHash(),p.sourceInstitutionCode(),p.sourceProductId(),p.institution(),p.productName(),p.mortgageTypeCode(),p.mortgageTypeName(),p.repaymentTypeCode(),p.repaymentTypeName(),p.rateTypeCode(),p.rateTypeName(),p.minRatePercent(),p.maxRatePercent(),d("6.1"),p.productCollectedAt(),p.termCollectedAt(),p.sourceObservedAt(),p.qualityStatus(),p.sourceType(),p.sourceMode(),p.productType(),p.purpose(),p.amountMin(),p.amountMax(),p.termMin(),p.termMax(),p.repaymentMethods(),p.eligibilityText(),p.constraints());var e=run(List.of(avg)).getFirst();assertThat(e.simulationAnnualRate()).isEqualByComparingTo(".061");assertThat(e.warnings()).contains("REPRESENTATIVE_AVERAGE_RATE_USED");}
 @Test void tiedScoresUseStableProductAndTermOrder(){var a=product(5,"4","5");var b=product(2,"4","5");var result=run(List.of(a,b));assertThat(result.stream().filter(e->e.rank()==1).findFirst().orElseThrow().product().productTermId()).isEqualTo(2);}
 @Test void directRequestCalculatesLoanButDoesNotInventStressScore(){var request=new Request(null,d("590000000"),d("4000000"),30,List.of("AMORTIZING"),3);var e=engine.evaluate(request,List.of(product(1,"4","5")),snapshot(),null,simulation,AS_OF).getFirst();assertThat(e.loanResult()).isNotNull();assertThat(e.homeResult()).isNull();assertThat(e.status()).isEqualTo(Status.INSUFFICIENT_DATA);assertThat(e.limitations()).contains("POST_SCENARIO_METRICS_REQUIRE_HOME_SCENARIO","STRESS_CONTEXT_MISSING");}
 @Test void manifestValueIsImmutableWhenLaterProductValueChanges(){var original=run(List.of(product(1,"4","5"))).getFirst();var updated=run(List.of(product(1,"6","7"))).getFirst();assertThat(original.product().maxRatePercent()).isEqualByComparingTo("5");assertThat(updated.product().maxRatePercent()).isEqualByComparingTo("7");assertThat(original.simulationAnnualRate()).isNotEqualByComparingTo(updated.simulationAnnualRate());}
 private List<Evaluation> run(List<ProductRecord> products){var s=snapshot();var home=new SimulationEngine().home(s,ScenarioExamples.golden(s.financialSnapshotId()));var scenario=new ScenarioRecords.Scenario(id("scenario"),s.financialSnapshotId(),AS_OF,s.calculationRuleVersion(),SimulationEngine.RULE_VERSION,"HOME",null,null,home.input(),null,home,List.of(),List.of(),List.of(),List.of());return engine.evaluate(new Request(scenario.scenarioId(),d("590000000"),d("4000000"),30,List.of("AMORTIZING"),5),products,s,scenario,simulation,AS_OF);}
 private ProductRecord product(long term,String min,String max){return new ProductRecord(1,term,1,10,11,20,21,30,31,"a".repeat(64),"b".repeat(64),"001","P1","Demo Bank","Demo Loan","A","Apartment","E","Equal","F","Fixed",d(min),d(max),null,AS_OF.minusSeconds(3600),AS_OF.minusSeconds(3600),AS_OF.minusSeconds(3600),"SERVING","REAL_PRODUCT_DATA","DEMO_REPLAY","MORTGAGE","HOME",d("1"),d("900000000"),1,50,List.of("AMORTIZING"),"explicit test eligibility","none");}
 private ProductRecord copy(ProductRecord p,String quality,BigDecimal min,BigDecimal max,Integer termMin,Integer termMax,List<String> methods,String eligibility){return new ProductRecord(p.loanProductId(),p.productTermId(),p.termParentProductId(),p.productPublicationRunId(),p.termPublicationRunId(),p.productSourceRunId(),p.termSourceRunId(),p.productRawSnapshotId(),p.termRawSnapshotId(),p.productRawHash(),p.termRawHash(),p.sourceInstitutionCode(),p.sourceProductId(),p.institution(),p.productName(),p.mortgageTypeCode(),p.mortgageTypeName(),p.repaymentTypeCode(),p.repaymentTypeName(),p.rateTypeCode(),p.rateTypeName(),p.minRatePercent(),p.maxRatePercent(),p.avgRatePercent(),p.productCollectedAt(),p.termCollectedAt(),p.sourceObservedAt(),quality,p.sourceType(),p.sourceMode(),p.productType(),p.purpose(),min,max,termMin,termMax,methods,eligibility,p.constraints());}
 private Snapshot snapshot(){var input=new Input(id("user"),AS_OF,List.of(),List.of(fact("EXISTING_LOAN_BALANCE","30000000"),fact("SCHEDULED_MONTHLY_DEBT_SERVICE","600000"),fact("MONTHLY_FIXED_OBLIGATION","200000"),fact("MONTHLY_ESSENTIAL_EXPENSE","2200000")),d("120000000"),d("66000000"),List.of(new ClassifiedTransaction(id("income"),d("4800000"),"CREDIT",Category.INCOME),new ClassifiedTransaction(id("living"),d("2800000"),"DEBIT",Category.LIVING_EXPENSE),new ClassifiedTransaction(id("debt"),d("600000"),"DEBIT",Category.DEBT_SERVICE)),1,true,true,true,List.of());var calc=new TwinCalculator();return new Snapshot(id("snapshot"),input.financialUserId(),AS_OF,AS_OF,"COMPLETE",TwinCalculator.RULE_VERSION,calc.fingerprint(input),input,calc.calculate(input));}
 private Fact fact(String kind,String value){return new Fact(id(kind),kind,d(value),"USER_INPUT","DEMO_REPLAY",AS_OF,"KRW","demo");}private static final Instant AS_OF=Instant.parse("2026-09-21T10:00:00Z");private static BigDecimal d(String v){return new BigDecimal(v);}private static UUID id(String v){return UUID.nameUUIDFromBytes(v.getBytes(StandardCharsets.UTF_8));}
}
